"""Write docs/rules.md from rule metadata. Usage: python scripts/gen_rules_doc.py [--check]."""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from cspm.mapping import controls_for  # noqa: E402
from rules import ALL_RULES  # noqa: E402

TARGET = ROOT / "docs" / "rules.md"


def render() -> str:
    lines = [
        "# Rules",
        "",
        "Generated by `python scripts/gen_rules_doc.py` from rule metadata. Do not edit by hand.",
        "",
        f"{len(ALL_RULES)} rules. Severity is the base severity before scoring (see docs/scoring.md).",
        "",
        "| ID | Resource type | Severity | Title |",
        "|---|---|---|---|",
    ]
    for r in ALL_RULES:
        m = r.meta
        types = ", ".join(m.resource_types)
        lines.append(f"| [{m.id}](#{m.id.lower()}) | {types} | {m.severity_base.value} | {m.title} |")
    for rule in ALL_RULES:
        m = rule.meta
        frameworks = sorted({c.framework for c in controls_for(m.id)})
        lines += [
            "",
            f"## {m.id}",
            "",
            f"**{m.title}**",
            "",
            f"- Resource type: `{', '.join(m.resource_types)}`",
            f"- Base severity: {m.severity_base.value}",
            f"- Rationale: {m.rationale}",
            f"- Impact: {m.impact}",
            f"- Remediation: {m.remediation}",
            f"- Informed by: {', '.join(frameworks) if frameworks else 'none'}",
        ]
        lines += [f"- Reference: <{ref}>" for ref in m.references]
    return "\n".join(lines) + "\n"


def main(argv: list[str]) -> int:
    text = render()
    if "--check" in argv:
        current = TARGET.read_text(encoding="utf-8") if TARGET.exists() else ""
        if current != text:
            print("docs/rules.md is stale; run python scripts/gen_rules_doc.py")
            return 1
        return 0
    TARGET.write_text(text, encoding="utf-8", newline="\n")
    print(f"wrote {TARGET}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
